{"content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { callTool, listTools } from './server.mjs';

test('listTools returns ticket_create schema with additionalProperties:false', async () => {
  const tools = await listTools();
  assert.equal(tools.length, 1);
  assert.equal(tools[0].name, 'ticket_create');
  assert.equal(tools[0].inputSchema.additionalProperties, false);
  assert.ok(tools[0].inputSchema.required.includes('title'));
  assert.ok(tools[0].inputSchema.required.includes('description'));
});

test('creates ticket with default priority', async () => {
  const r = await callTool('ticket_create', { title: 'Bug', description: 'Broken' });
  assert.match(r.content[0].text, /t\d+/);
  assert.match(r.content[0].text, /normal/);
});

test('creates ticket with custom priority', async () => {
  const r = await callTool('ticket_create', { title: 'Urgent', description: 'Fix now', priority: 'high' });
  assert.match(r.content[0].text, /t\d+/);
  assert.match(r.content[0].text, /high/);
});

test('creates ticket with low priority', async () => {
  const r = await callTool('ticket_create', { title: 'Minor', description: 'Low prio', priority: 'low' });
  assert.match(r.content[0].text, /t\d+/);
  assert.match(r.content[0].text, /low/);
});

test('generates sequential ticket ids', async () => {
  const r1 = await callTool('ticket_create', { title: 'A', description: 'A' });
  const r2 = await callTool('ticket_create', { title: 'B', description: 'B' });
  const id1 = r1.content[0].text.match(/t(\d+)/)[1];
  const id2 = r2.content[0].text.match(/t(\d+)/)[1];
  assert.ok(Number(id2) > Number(id1));
});

test('rejects missing title', async () => {
  await assert.rejects(() => callTool('ticket_create', { description: 'No title' }), /title/);
});

test('rejects missing description', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'No desc' }), /description/);
});

test('rejects empty title', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: '', description: 'Desc' }), /title/);
});

test('rejects empty description', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'Title', description: '' }), /description/);
});

test('rejects whitespace-only title', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: '   ', description: 'Desc' }), /title/);
});

test('rejects whitespace-only description', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'Title', description: '  ' }), /description/);
});

test('rejects invalid priority', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'X', description: 'Y', priority: 'critical' }), /priority/);
});

test('rejects extra fields', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'X', description: 'Y', extra: 'no' }), /Unexpected/);
});

test('rejects unknown tool', async () => {
  await assert.rejects(() => callTool('unknown_tool', {}), /Unknown/);
});

test('rejects null title', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: null, description: 'Desc' }), /title/);
});

test('rejects null description', async () => {
  await assert.rejects(() => callTool('ticket_create', { title: 'Title', description: null }), /description/);
});
